package com.oms.inventory.service.impl;

import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.*;
import javax.annotation.Resource;
import java.math.BigDecimal;
import java.util.*;
import static com.oms.common.lucky.LuckyBagRules.*;
import static com.oms.inventory.service.impl.LuckyBagInventory.*;

/** Durable bag identity and atomic conversion of pool protection into original-batch order sources. */
@Service public class LuckyBagStock {
    @Resource JdbcTemplate db;
    @Resource LuckyBagInventory pools;

    @Transactional(rollbackFor=Exception.class,timeout=30,isolation=Isolation.READ_COMMITTED)
    public Map<String,Object> claim(String company,Map<String,Object> input){
        long channel=number(input,"channel_id"),quantity=number(input,"quantity");String tid=text(input,"platform_tid"),oid=text(input,"platform_oid"),bag=text(input,"sku_sn");
        require(channel>0&&com.oms.common.util.FulfillmentReference.valid(tid)&&(Boolean.TRUE.equals(input.get("gift"))?tid.matches("GIFT:[1-9][0-9]{0,18}:[1-9][0-9]{0,3}")&&oid.isEmpty():oid.matches("[0-9]{1,64}"))&&!bag.isEmpty()&&bag.length()<=50&&quantity>0&&quantity<=50,"福袋订单身份或数量无效，每个销售行最多50袋");
        Map<String,Object> def=pools.definition(company,bag);require(!def.isEmpty(),"福袋规则尚未核实");List<String> keys=skus(def);keys.add(bag);
        // Include old-version pool components so a rule publish cannot invert SKU locking order.
        keys.addAll(db.queryForList("SELECT DISTINCT s.sku_sn FROM oms_lucky_source s JOIN oms_lucky_pool p ON p.company_code=s.company_code AND p.id=s.pool_id WHERE p.company_code=? AND p.bag_sku=? AND p.channel_id=? AND p.state IN ('ACTIVE','DRAINING') AND (p.available_quantity>0 OR p.occupied_quantity>0)",String.class,company,bag,channel));require(new HashSet<>(keys).size()<=2000,"福袋跨版本组件来源过多，请先回收闲置保障");pools.lockSkus(company,keys);
        List<Map<String,Object>> old=db.queryForList("SELECT * FROM oms_lucky_claim WHERE company_code=? AND channel_id=? AND platform_tid=? AND platform_oid=? FOR UPDATE",company,channel,tid,oid);
        if(!old.isEmpty()){Map<String,Object> row=old.get(0);require(bag.equals(text(row,"bag_sku"))&&quantity==number(row,"quantity"),"已登记福袋需求与本次商品或袋数不同");require(!"CANCELED".equals(text(row,"state")),"福袋原需求已取消，不能重建占用");if(!"WAITING".equals(text(row,"state")))return object(row.get("snapshot_json"));}
        // Disabling stops new exposure/allocation; paid or in-flight sales still consume protected pools.
        List<Map<String,Object>> candidates=db.queryForList("SELECT * FROM oms_lucky_pool WHERE company_code=? AND bag_sku=? AND channel_id=? AND state IN ('ACTIVE','DRAINING') AND available_quantity>0 ORDER BY id LIMIT 100 FOR UPDATE",company,bag,channel);
        long ahead=db.queryForObject("SELECT COALESCE(SUM(quantity),0) FROM oms_lucky_claim WHERE company_code=? AND bag_sku=? AND channel_id=? AND state='WAITING' AND id<?",Long.class,company,bag,channel,old.isEmpty()?Long.MAX_VALUE:number(old.get(0),"id"));
        long available=db.queryForObject("SELECT COALESCE(SUM(available_quantity),0) FROM oms_lucky_pool WHERE company_code=? AND bag_sku=? AND channel_id=? AND state IN ('ACTIVE','DRAINING')",Long.class,company,bag,channel);if(available<quantity+ahead){Map<String,Object> waiting=map("business_type","LUCKY_BAG","inventory_mode","VIRTUAL","sku_sn",bag,"goods_name",def.get("goods_name"),"revision",def.get("revision"),"quantity",quantity,"state","WAIT_STOCK","available_quantity",Math.max(0,available-ahead),"shortage_quantity",Math.max(0,quantity-Math.max(0,available-ahead)),"message","福袋渠道保障余额不足，保留袋数需求等待补足");db.update("INSERT INTO oms_lucky_claim(company_code,channel_id,platform_tid,platform_oid,bag_sku,quantity,state,snapshot_json) VALUES (?,?,?,?,?,?,'WAITING',?) ON DUPLICATE KEY UPDATE id=id",company,channel,tid,oid,bag,quantity,encode(waiting));pools.project(company,bag,channel);return waiting;}
        List<Map<String,Object>> units=new ArrayList<>();Map<Long,Map<String,Object>> sourceFacts=new TreeMap<>();Map<Long,Long> takes=new TreeMap<>();
        int orderUnit=0;for(Map<String,Object> pool:candidates){int take=Math.toIntExact(Math.min(quantity-orderUnit,number(pool,"available_quantity")));if(take==0)break;long poolId=number(pool,"id");Map<String,Object> rule=object(pool.get("definition_json"));
            List<Map<String,Object>> sources=db.queryForList("SELECT s.*,p.store_code FROM oms_lucky_source s JOIN oms_lucky_pool p ON p.company_code=s.company_code AND p.id=s.pool_id WHERE s.company_code=? AND s.pool_id=? ORDER BY s.id FOR UPDATE",company,poolId);for(Map<String,Object> source:sources)sourceFacts.put(number(source,"id"),source);
            List<Map<String,Object>> selected;
            if("PRESET".equals(text(rule,"mode"))){selected=db.queryForList("SELECT * FROM oms_lucky_unit WHERE company_code=? AND pool_id=? AND state='AVAILABLE' ORDER BY id LIMIT ? FOR UPDATE",company,poolId,take);require(selected.size()==take,"预制组合池可用袋数与明细不一致");}
            else{List<Map<String,Object>> facts=new ArrayList<>();for(Map<String,Object> source:sources)facts.add(map("batch_id",source.get("batch_id"),"sku_sn",source.get("sku_sn"),"available",number(source,"quantity")-number(source,"occupied_quantity")-number(source,"consumed_quantity")-number(source,"released_quantity"),"unit_cost",source.get("unit_cost")));selected=com.oms.common.lucky.LuckyBagRules.plan(rule,facts,take,Objects.hash(company,channel,tid,oid,poolId));}
            Map<Long,Map<String,Object>> byBatch=new HashMap<>();for(Map<String,Object> s:sources)byBatch.put(number(s,"batch_id"),s);
            long sequence=db.queryForObject("SELECT COALESCE(MAX(sequence_no),0) FROM oms_lucky_unit WHERE company_code=? AND pool_id=?",Long.class,company,poolId);
            for(Map<String,Object> unit:selected){List<Map<String,Object>> components=unit.get("components_json")==null?rows(unit.get("components")):array(unit.get("components_json"));
                for(Map<String,Object> component:components){Map<String,Object> source=byBatch.get(number(component,"batch_id"));require(source!=null,"福袋组件原批次来源缺失");component.put("source_id",source.get("id"));component.put("store_code",pool.get("store_code"));takes.merge(number(source,"id"),1L,Long::sum);}
                long unitId=unit.get("id")==null?pools.insert("INSERT INTO oms_lucky_unit(company_code,pool_id,sequence_no,components_json,cost,state,channel_id,platform_tid,platform_oid,order_unit) VALUES (?,?,?,?,?,'RESERVED',?,?,?,?)",company,poolId,++sequence,encode(components),unit.get("cost"),channel,tid,oid,orderUnit+1):number(unit,"id");
                if(unit.get("id")!=null)require(db.update("UPDATE oms_lucky_unit SET state='RESERVED',platform_tid=?,platform_oid=?,order_unit=? WHERE company_code=? AND id=? AND state='AVAILABLE'",tid,oid,orderUnit+1,company,unitId)==1,"预制福袋已被其他订单领取");
                units.add(map("unit_id",unitId,"unit",++orderUnit,"pool_id",poolId,"revision",rule.get("revision"),"store_code",pool.get("store_code"),"components",components,"cost",unit.get("cost")));
            }
            require(db.update("UPDATE oms_lucky_pool SET available_quantity=available_quantity-?,occupied_quantity=occupied_quantity+? WHERE company_code=? AND id=? AND state IN ('ACTIVE','DRAINING') AND available_quantity>=?",take,take,company,poolId,take)==1,"福袋渠道余额已变化，已回滚");
        }
        require(orderUnit==quantity,"福袋整袋分配不完整，已回滚");Map<String,Long> quantities=new TreeMap<>();for(Map.Entry<Long,Long> entry:takes.entrySet()){Map<String,Object> source=sourceFacts.get(entry.getKey());String sku=text(source,"sku_sn");long q=entry.getValue();require(db.update("UPDATE oms_lucky_source SET occupied_quantity=occupied_quantity+? WHERE company_code=? AND id=? AND quantity-occupied_quantity-consumed_quantity-released_quantity>=?",q,company,entry.getKey(),q)==1,"福袋组件保障余额不足");quantities.merge(sku,q,Long::sum);}
        Map<String,Long> demands=new TreeMap<>();for(Map.Entry<String,Long> entry:quantities.entrySet()){String sku=entry.getKey();long q=entry.getValue();require(db.queryForObject("SELECT COUNT(*) FROM oms_order_stock_demand WHERE company_code=? AND channel_id=? AND platform_tid=? AND platform_oid=? AND sku_sn=?",Long.class,company,channel,tid,oid,sku)==0,"福袋组件已存在其他库存需求，不能覆盖");long demand=pools.insert("INSERT INTO oms_order_stock_demand(company_code,channel_id,platform_tid,platform_oid,sku_sn,demand_quantity,reserved_quantity,status,reason,reason_code,line_kind,component_quantity,lucky_sku) VALUES (?,?,?,?,?,?,?,'RESERVED','','',?,0,?)",company,channel,tid,oid,sku,q,q,Boolean.TRUE.equals(input.get("gift"))?"GIFT":"SALE",bag);demands.put(sku,demand);
            require(db.update("UPDATE oms_inventory SET allocated_stock=allocated_stock-?,reserved_stock=reserved_stock+?,version=version+1 WHERE company_code=? AND sku_sn=? AND allocated_stock>=?",q,q,company,sku,q)==1,"福袋组件公司保障库存不足");db.update("INSERT INTO oms_channel_inventory(company_code,channel_id,sku_sn,reserved_stock) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE reserved_stock=reserved_stock+VALUES(reserved_stock),version=version+1",company,channel,sku,q);
            db.update("INSERT INTO oms_order_stock_event(company_code,demand_id,action,quantity,message) VALUES (?,?,'RESERVE',?,'福袋原批次保障转订单占用')",company,demand,q);
        }
        Map<Long,Long> orderSources=new HashMap<>();for(Map.Entry<Long,Long> entry:takes.entrySet()){Map<String,Object> source=sourceFacts.get(entry.getKey());long id=pools.insert("INSERT INTO oms_order_stock_source(demand_id,company_code,sku_sn,store_code,source_type,source_id,quantity,reserved) VALUES (?,?,?,?,'LUCKY',?,?,1)",demands.get(text(source,"sku_sn")),company,source.get("sku_sn"),source.get("store_code"),entry.getKey(),entry.getValue());orderSources.put(entry.getKey(),id);}
        for(Map<String,Object> unit:units){for(Map<String,Object> component:rows(unit.get("components")))component.put("stock_source_id",orderSources.get(number(component,"source_id")));db.update("UPDATE oms_lucky_unit SET components_json=? WHERE company_code=? AND id=?",encode(unit.get("components")),company,unit.get("unit_id"));}
        Map<String,String> names=new HashMap<>();for(Map<String,Object> unit:units)for(Map<String,Object> c:rows(unit.get("components")))names.put(text(c,"sku_sn"),text(c,"goods_name"));List<Map<String,Object>> components=new ArrayList<>();for(Map.Entry<String,Long> entry:quantities.entrySet())components.add(map("sku_sn",entry.getKey(),"quantity",entry.getValue(),"goods_name",names.getOrDefault(entry.getKey(),entry.getKey())));
        Map<String,Object> snapshot=map("business_type","LUCKY_BAG","inventory_mode","VIRTUAL","sku_sn",bag,"goods_name",def.get("goods_name"),"revision",def.get("revision"),"enabled",1,"quantity",quantity,"units",units,"components",components);
        db.update("INSERT INTO oms_lucky_claim(company_code,channel_id,platform_tid,platform_oid,bag_sku,quantity,snapshot_json) VALUES (?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE state='RESERVED',snapshot_json=VALUES(snapshot_json)",company,channel,tid,oid,bag,quantity,encode(snapshot));for(String sku:quantities.keySet())OrderStockService.refresh(db,company,sku,channel);pools.project(company,bag,channel);return snapshot;
    }
    @SuppressWarnings("unchecked") static List<Map<String,Object>> array(Object raw){try{return rows(new com.fasterxml.jackson.databind.ObjectMapper().readValue(raw.toString(),List.class));}catch(Exception e){throw new IllegalArgumentException("福袋组成数组无法读取");}}

    /** Source counters change before generic company/channel balances; caller holds stock locks. */
    public static void releaseSource(JdbcTemplate db,String company,Map<String,Object> source,long quantity){require(db.update("UPDATE oms_lucky_source SET occupied_quantity=occupied_quantity-? WHERE company_code=? AND id=? AND sku_sn=? AND occupied_quantity>=?",quantity,company,source.get("source_id"),source.get("sku_sn"),quantity)==1,"福袋原组件占用不足");}
    public static void consumeSource(JdbcTemplate db,String company,Map<String,Object> source,long quantity){require(db.update("UPDATE oms_lucky_source SET occupied_quantity=occupied_quantity-?,consumed_quantity=consumed_quantity+? WHERE company_code=? AND id=? AND sku_sn=? AND occupied_quantity>=?",quantity,quantity,company,source.get("source_id"),source.get("sku_sn"),quantity)==1,"福袋原组件占用不足");}
    public static long batchOwed(JdbcTemplate db,String company,long batch){return db.queryForObject("SELECT COALESCE(SUM(quantity-consumed_quantity-released_quantity),0) FROM oms_lucky_source WHERE company_code=? AND batch_id=?",Long.class,company,batch);}
    public static boolean protectedSource(String type){return "LOCK".equals(type)||"LUCKY".equals(type);}
    public static void project(JdbcTemplate db,String company,String bag,long channel){Map<String,Object> q=db.queryForMap("SELECT COALESCE(SUM(IF(state='ACTIVE',available_quantity,0)),0) available,COALESCE(SUM(occupied_quantity),0) occupied FROM oms_lucky_pool WHERE company_code=? AND bag_sku=? AND channel_id=?",company,bag,channel);long waiting=waiting(db,company,bag,channel);db.update("UPDATE oms_channel_inventory SET available_stock=?,allocated_stock=?,reserved_stock=?,quota_stock=0,quota_reserved_stock=0,pending_stock=?,version=version+1 WHERE company_code=? AND sku_sn=? AND channel_id=?",db.queryForObject("SELECT COUNT(*) FROM oms_lucky_definition WHERE company_code=? AND sku_sn=? AND JSON_EXTRACT(definition_json,'$.enabled')=1",Long.class,company,bag)>0?Math.max(0,number(q,"available")-waiting):0,q.get("available"),q.get("occupied"),waiting,company,bag,channel);}
    public static long waiting(JdbcTemplate db,String company,String bag,long channel){return db.queryForObject("SELECT COALESCE(SUM(quantity),0) FROM oms_lucky_claim WHERE company_code=? AND bag_sku=? AND channel_id=? AND state='WAITING'",Long.class,company,bag,channel);}
    public static void cancelWaiting(JdbcTemplate db,String company,long channel,String tid){List<String> bags=db.queryForList("SELECT DISTINCT bag_sku FROM oms_lucky_claim WHERE company_code=? AND channel_id=? AND platform_tid=? AND state='WAITING'",String.class,company,channel,tid);db.update("UPDATE oms_lucky_claim SET state='CANCELED' WHERE company_code=? AND channel_id=? AND platform_tid=? AND state='WAITING'",company,channel,tid);for(String bag:bags)project(db,company,bag,channel);}
    /** Whole-bag completion is derived from original stock-source receipts; partial components retain a hold. */
    public static void reconcile(JdbcTemplate db,String company,long channel,String tid){
        List<Map<String,Object>> claims=db.queryForList("SELECT * FROM oms_lucky_claim WHERE company_code=? AND channel_id=? AND platform_tid=? AND state<>'WAITING' FOR UPDATE",company,channel,tid);
        for(Map<String,Object> claim:claims){String oid=text(claim,"platform_oid"),bag=text(claim,"bag_sku");List<Map<String,Object>> units=db.queryForList("SELECT u.*,p.definition_json,p.state pool_state FROM oms_lucky_unit u JOIN oms_lucky_pool p ON p.company_code=u.company_code AND p.id=u.pool_id WHERE u.company_code=? AND u.channel_id=? AND u.platform_tid=? AND u.platform_oid=? ORDER BY u.order_unit,u.id FOR UPDATE",company,channel,tid,oid);
            Map<Long,Long> shipped=new HashMap<>(),released=new HashMap<>();for(Map<String,Object> s:db.queryForList("SELECT s.* FROM oms_order_stock_source s JOIN oms_order_stock_demand d ON d.company_code=s.company_code AND d.id=s.demand_id WHERE d.company_code=? AND d.channel_id=? AND d.platform_tid=? AND d.platform_oid=? AND s.source_type='LUCKY'",company,channel,tid,oid)){shipped.put(number(s,"id"),number(s,"outbound_quantity"));released.put(number(s,"id"),number(s,"released_quantity")+(number(s,"reserved")==0?number(s,"quantity")-number(s,"outbound_quantity"):0));}
            for(Map<String,Object> unit:units){List<Map<String,Object>> components=array(unit.get("components_json"));Map<Long,Long> wanted=new HashMap<>();for(Map<String,Object> c:components)wanted.merge(number(c,"stock_source_id"),1L,Long::sum);
                boolean out=wanted.entrySet().stream().allMatch(e->shipped.getOrDefault(e.getKey(),0L)>=e.getValue()),back=wanted.entrySet().stream().allMatch(e->released.getOrDefault(e.getKey(),0L)>=e.getValue());String state=text(unit,"state");
                if("SHIPPED".equals(state)){for(Map.Entry<Long,Long> e:wanted.entrySet())shipped.computeIfPresent(e.getKey(),(k,v)->v-e.getValue());continue;}
                if("RETURNED".equals(state)||"AVAILABLE".equals(state)){for(Map.Entry<Long,Long> e:wanted.entrySet())released.computeIfPresent(e.getKey(),(k,v)->v-e.getValue());continue;}
                if("PARTIAL".equals(state)){for(Map<String,Object> c:components){long source=number(c,"stock_source_id");Map<Long,Long> use=number(c,"settled_out")==1?shipped:released;use.computeIfPresent(source,(k,v)->v-1);}continue;}
                if(!"RESERVED".equals(state))continue;
                boolean settled=!wanted.isEmpty()&&wanted.entrySet().stream().allMatch(e->shipped.getOrDefault(e.getKey(),0L)+released.getOrDefault(e.getKey(),0L)>=e.getValue());
                if(!out&&!back&&settled){for(Map<String,Object> c:components){long source=number(c,"stock_source_id");boolean sent=shipped.getOrDefault(source,0L)>0;c.put("settled_out",sent?1:0);(sent?shipped:released).computeIfPresent(source,(k,v)->v-1);}db.update("UPDATE oms_lucky_unit SET state='PARTIAL',components_json=? WHERE company_code=? AND id=? AND state='RESERVED'",encode(components),company,unit.get("id"));require(db.update("UPDATE oms_lucky_pool SET occupied_quantity=occupied_quantity-1,consumed_quantity=consumed_quantity+1 WHERE company_code=? AND id=? AND occupied_quantity>=1",company,unit.get("pool_id"))==1,"福袋部分履约余额不足");continue;}
                if(out||back){boolean preset="PRESET".equals(text(object(unit.get("definition_json")),"mode"));String next=out?"SHIPPED":preset?"AVAILABLE":"RETURNED";db.update("UPDATE oms_lucky_unit SET state=? WHERE company_code=? AND id=? AND state='RESERVED'",next,company,unit.get("id"));require(db.update("UPDATE oms_lucky_pool SET occupied_quantity=occupied_quantity-?,consumed_quantity=consumed_quantity+?,available_quantity=available_quantity+? WHERE company_code=? AND id=? AND occupied_quantity>=1",1,out?1:0,back?1:0,company,unit.get("pool_id"))==1,"福袋占用袋数不足，已回滚");Map<Long,Long> use=out?shipped:released;for(Map.Entry<Long,Long> e:wanted.entrySet())use.computeIfPresent(e.getKey(),(k,v)->v-e.getValue());}
            }
            long active=db.queryForObject("SELECT COUNT(*) FROM oms_lucky_unit WHERE company_code=? AND channel_id=? AND platform_tid=? AND platform_oid=? AND state='RESERVED'",Long.class,company,channel,tid,oid);if(active==0)db.update("UPDATE oms_lucky_claim SET state=? WHERE company_code=? AND id=?",db.queryForObject("SELECT COUNT(*) FROM oms_lucky_unit WHERE company_code=? AND channel_id=? AND platform_tid=? AND platform_oid=? AND state IN ('SHIPPED','PARTIAL')",Long.class,company,channel,tid,oid)>0?"DONE":"CANCELED",company,claim.get("id"));project(db,company,bag,channel);
        }
    }
}
